// A sending-provider Integration. Credentials are write-only: the config is returned with secrets
// redacted.
// Ref: #/components/schemas/IntegrationResource
type IntegrationResource struct {
	// Unique identifier.
	ID EntityId `json:"id"`
	// Human-readable label.
	Name string `json:"name"`
	// Delivery channel.
	Channel IntegrationChannel `json:"channel"`
	// Concrete provider.
	Provider IntegrationProvider `json:"provider"`
	// Whether this integration may be used for sending.
	Enabled bool `json:"enabled"`
	// Whether this is the default provider for its channel.
	IsDefault bool `json:"isDefault"`
	// Provider limit set on the Integration: most messages per second; null means none.
	MaxPerSecond NilInt32 `json:"maxPerSecond"`
	// Provider limit set on the Integration: most messages per rolling 24 hours; null means none.
	MaxPerDay NilInt32 `json:"maxPerDay"`
	// The Provider limit as enforced and 24-hour usage.
	ProviderLimit ProviderLimitStatus `json:"providerLimit"`
	// Provider config (secrets redacted).
	Config IntegrationConfig `json:"config"`
	// The Preset this Integration's provider callbacks are read with; null when it receives none.
	Preset NilString `json:"preset"`
	// The Preset's params as saved. A secret param (`writeOnly` in the Preset's schema) is shown as
	// `********`, never its value.
	Params IntegrationResourceParams `json:"params"`
	// Names of the secret params that are rotating: a retiring value is still accepted beside the current
	// one.
	SecretsRetiring []string `json:"secretsRetiring"`
	// Where the provider posts this Integration's callbacks: paste it into the provider. The key in it is
	// an address, not the authentication (the Preset's signature or secret is).
	HookUrl string `json:"hookUrl"`
	// When the integration was archived; null while it is kept. An archived integration is never the
	// default and takes no new work, but its hook still reads the provider's callbacks.
	ArchivedAt OptNilTimestamp `json:"archivedAt"`
	// Creation timestamp.
	CreatedAt Timestamp `json:"createdAt"`
	// Last update timestamp.
	UpdatedAt Timestamp `json:"updatedAt"`
}

